 const database=select('database-index-locks',['入口说数据库用了 700 毫秒，先确定它测了什么','索引先按键排列，再指向数据所在的位置','用两种数据分布推导候选工作量','索引也有价格，要让写和读一起验收','事务把多步写入变成一个可判定的结果','索引命中了，为什么写请求还是要等','用两个连接区分访问路径和写者竞争','验收：两起同名告警需要不同的修复','配套代码与本次运行结果']);
