 const cache=select('cache-consistency',['先回答“谁有资格说订单已经发货”','读穿旁路缓存的三个步骤','一次旧读怎样穿过成功的失效','用版本水位挡回旧值，它需要哪些前提','热点击穿与集中到期，先算回源预算','领先请求失败后，谁负责唤醒等待者','从事件回放走到真实事务','验收：为不同读者分别签一份承诺','四事件短回放的源码与结果']);
